compile.workshop:
variables {
    global:
        0: phase
        1: hits
}

rule ("condition transition") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.phase == False;
        Match Time > 0;
    }
    actions {
        Modify Global Variable(hits, Add, 1);
        Set Global Variable(phase, True);
        Wait(0.016, Ignore Condition);
    }
}

